const trig = $('Error Trigger').first().json;
const exec = trig.execution || {};
const wf = trig.workflow || {};
const err = exec.error || {};
const rawMsg = (err.message || err.description || 'Nieznany blad').toString();
const blob = (rawMsg + ' ' + (err.description || '')).toLowerCase();
const httpCode = String(err.httpCode || err.code || '');
const nodeName = (err.node && err.node.name) || exec.lastNodeExecuted || '';
const wfName = wf.name || '';
const execId = exec.id || '';
const execUrl = exec.url || '';
const KLIENTKA_CHAT_ID = '7213159196';
let chatId = KLIENTKA_CHAT_ID;
try {
  const dataStr = JSON.stringify($('Pobierz Egzekucje').first().json || {});
  const grabNum = (s, key) => {
    let i = s.indexOf(key);
    if (i === -1) return null;
    i += key.length;
    if (s[i] === '"') i++;
    let num = '';
    if (s[i] === '-') { num += '-'; i++; }
    while (i < s.length && s[i] >= '0' && s[i] <= '9') { num += s[i]; i++; }
    return num.length ? num : null;
  };
  const found = grabNum(dataStr, '"chat":{"id":') || grabNum(dataStr, '"chat_id":');
  if (found) chatId = found;
} catch (e) {}
const has = (...frags) => frags.some(f => blob.includes(f));
const isTransient = JSON.stringify(err).toLowerCase().includes('is_transient')
  || (httpCode === '500' && has('unexpected error','please retry','was not able to process'));
if (isTransient) { return []; }
let powod = null, coZrobic = null, techniczny = false;
if (has('exceeded the quota of time','quota of time')) {
  powod = 'Skonczyly sie kredyty na renderowanie wideo (json2video).';
  coZrobic = 'Doladuj kredyty w panelu json2video i wygeneruj rolke ponownie.';
} else if (has('insufficient_quota','exceeded your current quota','billing hard limit','insufficient funds','insufficient_balance','payment required') || httpCode === '402') {
  powod = 'Skonczyly sie srodki na koncie OpenAI lub Perplexity.';
  coZrobic = 'Doladuj konto u dostawcy (OpenAI / Perplexity) i sprobuj ponownie.';
} else if (has('quota_exceeded') && has('elevenlabs','xi-api','voice')) {
  powod = 'Wykorzystany limit znakow lektora (ElevenLabs).';
  coZrobic = 'Odnow / doladuj plan ElevenLabs.';
} else if (has('rate limit','rate_limit','too many requests','retry after','flood') || httpCode === '429') {
  powod = 'Za duzo zapytan w krotkim czasie - usluga chwilowo odrzuca (limit predkosci).';
  coZrobic = 'Odczekaj 1-2 minuty i sprobuj ponownie.';
} else if (has('request entity too large','payload too large','too large','maximum context length','context_length_exceeded') || httpCode === '413') {
  powod = 'Zapytanie bylo zbyt duze (za duzo danych/tekstu naraz).';
  coZrobic = 'Sprobuj z krotszym tematem lub mniejsza liczba zdjec.';
  techniczny = true;
} else if (has('502','bad gateway','503','service unavailable','connection was aborted','server is offline','econnrefused','openresty')) {
  powod = 'Strona WordPress nie odpowiada (problem hostingu, nie automatyzacji).';
  coZrobic = 'Publikacja powtorzy sie, gdy strona wstanie. Jesli dlugo trwa - przekaz Nicolasowi.';
  techniczny = true;
} else if (has('authorization failed','unauthorized','invalid api key','check credentials','forbidden','missing_scope','invalid_grant','api key') || httpCode === '401' || httpCode === '403') {
  powod = 'Usluga odrzucila dostep (zly klucz lub uprawnienia) na kroku ' + (nodeName || '?') + '.';
  coZrobic = 'To wymaga poprawy konfiguracji - przekaz Nicolasowi.';
  techniczny = true;
} else if (has('webpage_curl_failed','webpage_media_empty','wrong file identifier','failed to get http url content')) {
  powod = 'Telegram nie pobral grafiki z linku (link wygasl lub niedostepny).';
  coZrobic = 'Przekaz Nicolasowi (poprawa sposobu wysylki grafik).';
  techniczny = true;
} else if (has('etimedout','timeout','socket hang up','econnreset','enotfound')) {
  powod = 'Usluga nie odpowiedziala na czas (chwilowy problem sieciowy).';
  coZrobic = 'Sprobuj ponownie za chwile.';
}
const stamp = $now.setZone('Europe/Warsaw').toFormat('yyyy-LL-dd HH:mm');
const meta = '(' + wfName + (nodeName ? ' - ' + nodeName : '') + ' - ' + stamp + ')';
let text;
if (powod) {
  text = 'Cos poszlo nie tak w automatyzacji\n\nPowod: ' + powod + '\nCo zrobic: ' + coZrobic + '\n\n' + meta;
  if (techniczny) { text += '\n\nDo przekazania Nicolasowi:\n' + rawMsg + '\nExec: ' + (execUrl || execId); }
} else {
  text = 'Cos poszlo nie tak - nietypowy blad. Prosze przekaz to Nicolasowi:\n\nWorkflow: ' + wfName + '\nKrok: ' + (nodeName || '-') + '\nBlad: ' + rawMsg + '\nKod HTTP: ' + (httpCode || '-') + '\nExec: ' + (execUrl || execId) + '\n' + meta;
}
return [{ json: { chat_id: chatId, text: text } }];
